import { PaneContext } from './pane.js';
import styles from './SplitView.module.css';

/**
 * A list and the thing picked from it, side by side: Material 3's
 * list-detail layout, an iPad's split view, the Mail app on a Mac. Used on
 * expanded windows only (lib/windowClass.ts) by the notebook and Settings;
 * on anything narrower each screen keeps the whole window as before.
 *
 * The list scrolls with the page, so everything a list already does on a
 * phone -- a header that folds away, more rows as you go -- keeps working.
 * The detail stays in view beside it and scrolls on its own, and it starts
 * at its top each time something new is picked (`detailKey`).
 *
 * The detail is the page's `<main>`; the list is labelled as its own region.
 */
export function SplitView({
  list,
  listLabel,
  detail,
  detailKey,
}: {
  list: React.ReactNode;
  listLabel: string;
  detail: React.ReactNode;
  detailKey: string;
}): React.JSX.Element {
  return (
    <div className={styles.split}>
      <section className={styles.list} aria-label={listLabel}>
        <PaneContext.Provider value="list">{list}</PaneContext.Provider>
      </section>
      <main className={styles.detail} key={detailKey}>
        <PaneContext.Provider value="detail">{detail}</PaneContext.Provider>
      </main>
    </div>
  );
}
